<script>
// DefiLlama protocols snapshot
let allProtocols = [];
let filtered = [];
let selectedId = null;

const boardEl = document.getElementById('board');
const detailEl = document.getElementById('detailView');
const searchEl = document.getElementById('search');
const filtersEl = document.getElementById('filters');

async function load() {
  document.getElementById('board').innerHTML = '<div class="loading">Memuat snapshot DefiLlama…</div>';
  try {
    const res = await fetch('https://api.llama.fi/protocols', { cache: 'no-store' });
