function buildFilters() {
  const cats = [...new Set(allProtocols.map(p => p.category).filter(Boolean))];
  filtersEl.innerHTML = '<div class="chip active" data-cat="">Semua</div>' +
    cats.map(c => `<div class="chip" data-cat="${c}">${c}</div>`).join('');
  filtersEl.addEventListener('click', e => {
    if (e.target.classList.contains('chip')) {
      document.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
      e.target.classList.add('active');
      applyFilter(e.target.dataset.cat);
    }
  });
  searchEl.addEventListener('input', applyFilter);
}

function isPreToken(p) {
  // No token address / symbol, not wrapped/staked, not a bridge or L2
  if (p.symbol && p.symbol !== '-') return false;
  if (p.category === 'L2' || p.category === 'Bridge' || p.category === 'Wrapped') return false;
  if (p.name.toLowerCase().includes('wrapped') || p.name.toLowerCase().includes('staked')) return false;
  return true;
}

function impliedValue(p) {
  // Kernel-implied value score: TVL * category weight * chain activity
  const tvl = p.tvl || 0;
  const weights = { 'CDP': 1.4, 'Lending': 1.3, 'Dex': 1.2, 'Yield': 1.1, 'Options': 1.1, 'Derivatives': 1.1, 'NFT': 1.0, 'Gaming': 1.0, 'Social': 0.9, 'Payments': 0.9, 'Other': 0.8 };
  const w = weights[p.category] || 0.8;
  const chainMult = p.chains && p.chains.length > 1 ? 1.15 : 1.0;
  return Math.round(tvl * w * chainMult);
}

function renderBoard() {
  boardEl.innerHTML = '';
  if (filtered.length === 0) {
    boardEl.innerHTML = '<div class="empty">Tidak ada protokol yang cocok.</div>';
    return;
  }
  filtered.forEach((p, i) => {
    const score = impliedValue(p);
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `
      <div class="rank">#${i + 1}</div>
      <span class="cat">${p.category || '—'}</span>
      <h3>${p.name}</h3>
      <div class="tvl">TVL: $${(p.tvl || 0).toLocaleString()}</div>
      <div class="score">Implied value: $${score.toLocaleString()}</div>
      <div style="font-size:0.75rem;color:#64748b">${p.chains ? p.chains.join(', ') : '—'}</div>
    `;
    card.onclick = () => openDetail(p);
    boardEl.appendChild(card);
  });
  document.getElementById('statTop').textContent = '$' + (filtered[0] ? impliedValue(filtered[0]).toLocaleString() : '-');
}

function applyFilter(cat) {
  const q = searchEl.value.toLowerCase();
  const preTokenOnly = true; // This bounty: only pre-token protocols
  filtered = allProtocols.filter(p => {
    if (!isPreToken(p)) return false;
    if (cat && p.category !== cat) return false;
    if (q && !p.name.toLowerCase().includes(q)) return false;
    return true;
  });
  filtered.sort((a, b) => impliedValue(b) - impliedValue(a));
  document.getElementById('statTotal').textContent = allProtocols.length.toLocaleString();
  document.getElementById('statPreToken').textContent = allProtocols.filter(isPreToken).length.toLocaleString();
  renderBoard();
}

function openDetail(p) {
  const score = impliedValue(p);
  detailEl.innerHTML = `
    <a href="#" class="back" onclick="closeDetail(); return false;">← Kembali ke board</a>
    <h2>${p.name}</h2>
    <div class="detail-grid">
      <div class="detail-section">
        <h4>Ringkasan</h4>
        <p><b>Kategori:</b> ${p.category || '—'}</p>
        <p><b>TVL:</b> $${(p.tvl || 0).toLocaleString()}</p>
        <p><b>Chain:</b> ${p.chains ? p.chains.join(', ') : '—'}</p>
        <p><b>Deskripsi:</b> ${p.description || 'Belum tersedia.'}</p>
        <p><b>Implied value saat launch:</b> $${score.toLocaleString()}</p>
      </div>
      <div class="detail-section">
        <h4>Langkah farm (estimasi)</h4>
        <ul class="farm-steps">
          <li><b>1.</b> Kunjungi situs resmi ${p.name} dan dompet Web3 (Phantom / Solflare).</li>
          <li><b>2.</b> Hubungkan dompet ke jaringan yang tepat (${p.chains ? p.chains[0] : 'Solana'}).</li>
          <li><b>3.</b> Berikan likuiditas atau stake aset yang didukung protokol.</li>
          <li><b>4.</b> Aktifkan secara teratur untuk mencetak poin / potensi airdrop.</li>
          <li><b>5.</b> Pantau pengumuman token resmi dari tim protokol.</li>
        </ul>
      </div>
    </div>
  `;
  detailEl.style.display = 'block';
  boardEl.style.display = 'none';
  window.scrollTo(0, 0);
}

function closeDetail() {
  detailEl.style.display = 'none';
  boardEl.style.display = 'grid';
  window.scrollTo(0, 0);
}

load();
</script>
</body>
</html>

